pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: depositor address and deposit amount
    function testFuzz_property(address depositor, uint96 amount) public {
        // keep depositor non-zero and amount in a reasonable range
        vm.assume(depositor != address(0));
        uint256 bounded = bound(uint256(amount), 1, 1 ether);

        // deploy an adversarial callee that will revert on receive
        Reverter reverter = new Reverter();

        // fund the depositor so they can deposit
        vm.deal(depositor, bounded);

        // perform deposit from depositor
        vm.prank(depositor);
        c.deposit{value: bounded}();

        // now set the depositor's credit to be forwarded to the reverter by making the test
        // call withdrawAll from the reverter address; we need the credit mapping key to match
        // the msg.sender that withdrawAll will send to. So we transfer the credit by using
        // the depositor address as the actor that will call withdrawAll, but the recipient
        // of the low-level call is msg.sender (the caller). To simulate an external call
        // that fails, we must have msg.sender be an address with code that reverts on
        // receiving funds. Foundry cannot change msg.sender to a contract without a call,
        // so instead: we make the depositor be the Reverter contract by transferring the
        // deposited funds to the reverter contract and then adjusting flow: deployer acts
        // as the depositor by calling deposit from the reverter contract via vm.prank.

        // To correctly set credit[reverter] = bounded, we call deposit from the reverter contract.
        // First, fund the reverter so it can send value when calling deposit.
        vm.deal(address(reverter), bounded);
        vm.prank(address(reverter));
        c.deposit{value: bounded}();

        // Sanity: the contract should hold the funds
        // Now call withdrawAll as the reverter: when C attempts msg.sender.call{value: bounded}(''),
        // the reverter's fallback will revert, so in the reference implementation withdrawAll must revert.
        bool ok;
        vm.prank(address(reverter));
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for all inputs the reference MUST revert the withdraw when the callee reverts.
        // Therefore ok must be false for the correct contract; the mutant that omits the require will set ok=true
        // for some inputs (this one) because it swallows the failed call and returns normally.
        assertTrue(!ok);
    }
}

