        // set its credit by impersonating it depositing
        vm.deal(address(r), amt);
        vm.prank(address(r));
        c.deposit{value: amt}();

        // Now call withdrawAll from the reverter contract's address; its fallback will revert
        // Using try/catch to capture success/failure
        bool ok;
        vm.prank(address(r));
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // General asserted fact: after withdrawAll completes (either success or revert),
        // the contract's stored balance must equal the contract's native balance plus
        // the sum of remaining credits. Here we only have one remaining depositor (depositor)
        // whose credit we can read; the reverter's credit should remain consistent with balance.
        // Because credit mapping is private, we cannot read individual credits; however, the
        // intended one-statement mutant causes address(c).balance to differ from the internal
        // balance when the external call reverts. We therefore assert that internal balance equals
        // address(c).balance (since if all credits were withdrawn or correctly updated these match).
        // This holds for the reference for all inputs; the mutant may break it when the external call reverts.
        (bool success, bytes memory data) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        // after an extra call attempt (harmless), assert the invariant: internal balance equals on-chain balance
        // we read internal "balance" via auto-generated getter (it is internal in original but for this test we assume public named 'balance' exists per instructions)
        // However the contract C declares 'uint balance;' without public — cannot read it. Instead we assert that
        // address(c).balance is equal to the total deposited minus any successful transfers out; for our scenario,
        // if the last withdrawAll reverted, the contract should still hold both deposits (2 * amt). If it succeeded,
        // it should have decreased by amt. The reference guarantees that after withdrawAll completes, address(c).balance
        // equals the expected on-chain value: if ok==false then address(c).balance == 2*amt, else address(c).balance == amt.

        if (!ok) {
            assertTrue(address(c).balance == 2 * amt);
        } else {
            assertTrue(address(c).balance == amt);
